import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"ADR-0007：relay→直连的升级重试改为 make-before-break，不再整段拆除会话","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0007-make-before-break-ice-upgrade.md","filePath":"adr/0007-make-before-break-ice-upgrade.md"}'),d={name:"adr/0007-make-before-break-ice-upgrade.md"};function i(s,e,l,c,n,p){return a(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="adr-0007-relay→直连的升级重试改为-make-before-break-不再整段拆除会话" tabindex="-1">ADR-0007：relay→直连的升级重试改为 make-before-break，不再整段拆除会话 <a class="header-anchor" href="#adr-0007-relay→直连的升级重试改为-make-before-break-不再整段拆除会话" aria-label="Permalink to &quot;ADR-0007：relay→直连的升级重试改为 make-before-break，不再整段拆除会话&quot;">​</a></h1><ul><li><strong>状态</strong>：已接受（Accepted）——2026-10-03 落地，见文末「决策记录」</li><li><strong>日期</strong>：2026-09-23</li><li><strong>关联</strong>：ADR-0006（信令在中继上回退；本文复用其 <code>peerSignaler</code> 与&quot;待确认问题 2&quot;里埋下的 <code>attempt_id</code>）、ADR-0002（ICE candidate race fix）</li></ul><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p><code>probe_upgrade.go</code> 里&quot;relay 用久了定期重试直连&quot;的机制，目前是整个 <code>Probe</code> 全量重启（break-before-make）：先把 WireGuard peer 整个删掉（<code>UAPI: Removing all allowedips</code> / <code>UAPI: Removing</code>），再重新走 ICE 与 relay 双轨发现。代码自己的注释也承认这一点：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// The retry is a full probe restart (the signaling has no &quot;upgrade only&quot; flag),</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// which costs a brief tunnel interruption, so attempts back off exponentially.</span></span></code></pre></div><p>问题是：每次升级尝试，不管最后成不成功，都会先造成一次真实的连接中断。如果 ICE 长期打不通（环境限制——本机代理接管了 UDP、对称 NAT、STUN 不可达等），&quot;尝试升级 → 中断 → 失败 → 退避后再试&quot;这个循环会无限重复，relay 连接永远等不到一段真正稳定、不被自己打断的窗口。</p><p>本文提议把升级尝试改成 make-before-break：在不影响现有 relay 连接的前提下，后台并行试探直连，试通了再原地把 WireGuard 的 endpoint 切过去；试不通，现有连接全程不受影响。</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><h3 id="当晚复现-2026-09-23-cloud-node-1-环境" tabindex="-1">当晚复现（2026-09-23，cloud-node-1 环境） <a class="header-anchor" href="#当晚复现-2026-09-23-cloud-node-1-环境" aria-label="Permalink to &quot;当晚复现（2026-09-23，cloud-node-1 环境）&quot;">​</a></h3><p>用 CLI 连 cloud-node-1（<code>app-id: macbook-pro.local</code>），relay-ready 建立约 114 秒后（与 <code>upgradeBaseInterval = 2 * time.Minute</code> 的首次重试时间点吻合），cloud-node-1 侧日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>time=...15:15:40.589Z level=DEBUG ... msg=&quot;SYN on active Relay session — remote restarted, triggering restart&quot; mod=relay-dialer remoteId=12433780925455272978</span></span>
<span class="line"><span>time=...15:15:40.589Z level=DEBUG ... msg=&quot;state transition&quot; mod=probe-factory remoteId=macbook-pro.local from=relay-ready to=failed</span></span>
<span class="line"><span>DEBUG: () 2026/09/23 15:15:40 peer(rI2p…Z0lc) - UAPI: Removing all allowedips</span></span>
<span class="line"><span>DEBUG: () 2026/09/23 15:15:40 peer(rI2p…Z0lc) - UAPI: Removing</span></span>
<span class="line"><span>DEBUG: () 2026/09/23 15:15:40 peer(rI2p…Z0lc) - Stopping</span></span></code></pre></div><p>这次重启恰好落在一次 <code>ping 10.96.0.2</code> 测试期间：抓包确认测试流量确实送达了 cloud-node-1 所在容器的中继 TCP 连接（<code>docker0</code>/<code>veth</code> 层面看到了对应字节数的突发流量），但 WireGuard peer 在同一时刻被整个移除，包无处可送，ping 全部超时。这一度被误判为&quot;FERRY 中继数据面不转发包&quot;，回头用时间线核对才发现是升级重试拆链路造成的假象。</p><h3 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h3><ol><li><code>internal/server/transport/probe_upgrade.go</code> 的 <code>tryUpgrade()</code>（<code>upgradeBaseInterval = 2 分钟</code>，翻倍退避到 <code>upgradeMaxInterval = 30 分钟</code>）调用 <code>p.upgradeRestart()</code> / <code>p.restart()</code>——一次完整的 probe 重启，等价于&quot;当作这个 peer 重新连接一次&quot;。</li><li>这次重启产生的信令（<code>HANDSHAKE_SYN</code>），在接收端（<code>internal/server/transport/relay_dialer.go</code>）眼里，和&quot;对端进程真的重启了&quot;没有任何区别。现有的 <code>relaySynGrace</code>（5 秒宽限期，ADR-0006 留下的时间启发式）只保护&quot;会话刚形成时的重传&quot;，保护不了&quot;会话已经稳定运行了很久，这次 SYN 其实是一次后台升级探测&quot;——一律触发 <code>onRestart()</code>，把整个 WireGuard peer 拆掉重建。</li><li>当晚同时确认：测试机上的本机代理（Clash，TUN 模式接管了包括 UDP 在内的全部默认路由）导致 STUN 探测全部超时，ICE 候选收集失败，直连在这个环境下永远打不通。这意味着像 cloud-node-1 这样的场景会持续每 2 / 4 / 8 / … 分钟重复一次&quot;尝试升级 → 中断 → 失败&quot;的循环，永远等不到退避封顶后的安静期。</li></ol><p>Clash 本身是本机环境问题，不是本文要解决的；但它把&quot;升级重试的中断代价&quot;这个已知设计缺陷的影响放大到了显性可见、可复现的程度，值得借这次一并修掉。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><ol><li>一次失败的升级尝试不能中断正在工作的 relay 连接——数据面（WireGuard peer/AllowedIPs 不变）和信令面（对端不能把这次探测误判为&quot;重启&quot;）都不能动。</li><li>升级尝试成功时，WireGuard 的 endpoint 原地切换到直连地址；除了这次切换本身带来的一次路径迁移，不产生额外中断。</li><li>接收端（非 initiator）能区分&quot;这是一次后台升级探测&quot;还是&quot;对端真的重启了&quot;，前者不触发 <code>onRestart()</code>。</li><li>新旧版本节点互通：旧版本节点收不到新字段（或不认识）时，安全回退到现在的整段重启行为——不是本文要优化的场景，但不能让旧节点崩溃或状态错乱。</li></ol><p>非目标：改变 relay 数据面协议本身（ADR-0005 范围）、改变&quot;ICE 优先于 relay&quot;的判定逻辑、解决 Clash 一类的本机网络环境问题。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><h3 id="_1-信令包新增-这是一次升级探测-标记" tabindex="-1">1. 信令包新增&quot;这是一次升级探测&quot;标记 <a class="header-anchor" href="#_1-信令包新增-这是一次升级探测-标记" aria-label="Permalink to &quot;1. 信令包新增&quot;这是一次升级探测&quot;标记&quot;">​</a></h3><p><code>SignalPacket.Handshake</code>（<code>internal/signal/signal.go</code>）新增：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Handshake</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Timestamp       </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  \`json:&quot;timestamp,omitempty&quot;\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	PeerInfo        []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">byte</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`json:&quot;peer_info,omitempty&quot;\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	IsUpgradeProbe  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   \`json:&quot;is_upgrade_probe,omitempty&quot;\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	AttemptID       </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`json:&quot;attempt_id,omitempty&quot;\`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 复用 ADR-0006 留的字段</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>旧版本节点不认识这两个字段，JSON 反序列化时直接丢弃，行为回退到现在的&quot;整段重启&quot;——满足新旧互通的目标。</p><h3 id="_2-升级尝试不再触碰现有-probe-wireguard-状态" tabindex="-1">2. 升级尝试不再触碰现有 Probe/WireGuard 状态 <a class="header-anchor" href="#_2-升级尝试不再触碰现有-probe-wireguard-状态" aria-label="Permalink to &quot;2. 升级尝试不再触碰现有 Probe/WireGuard 状态&quot;">​</a></h3><p><code>probe_upgrade.go</code> 的 <code>tryUpgrade()</code> 不再调用 <code>p.restart()</code> / <code>p.upgradeRestart()</code>。改为启动一个新增的 <code>shadowICEDialer</code>（<code>internal/server/transport/probe_shadow_upgrade.go</code>，新文件）：</p><ul><li>复用 <code>ice_dialer.go</code> 的候选收集与 connectivity check 逻辑，但<strong>不经过 <code>StateMachine</code></strong>，不调用 <code>configurator.RegisterPeer</code> / <code>RemovePeer</code>，只做纯粹的 ICE 协商。</li><li>生成一次性 <code>attemptID</code>，<code>peerSignaler</code> 发出的 SYN/OFFER/ANSWER 都带 <code>IsUpgradeProbe: true</code> + 这个 <code>attemptID</code>。</li><li>达到 ICE <code>Connected</code>（真正的 connectivity check 通过，不是&quot;候选收集完成&quot;）才算成功。</li><li>60 秒拿不到结果就放弃，按 <code>upgradeDelay(attempts+1)</code> 退避到下一次——不触碰现有连接，不触发 <code>probe.restart()</code>。</li></ul><h3 id="_3-升级成功后原地切换-endpoint" tabindex="-1">3. 升级成功后原地切换 endpoint <a class="header-anchor" href="#_3-升级成功后原地切换-endpoint" aria-label="Permalink to &quot;3. 升级成功后原地切换 endpoint&quot;">​</a></h3><p>只调用 <code>configurator.SetEndpoint(pubKey, newDirectAddr, keepalive)</code>；不调用 <code>RegisterPeer</code>（AllowedIPs 没变，不需要重新下发）、不调用 <code>RemovePeer</code>。机制上类似现有 <code>probe_endpoint.go</code> 里&quot;端点纠偏&quot;（<code>ReassertDirectEndpoint</code>）已经在做的原地替换，区别是这次是主动发起而非被动纠偏。<code>probe.currentTransport</code> 原地替换为新的 ICE transport，旧的 relay transport 优雅关闭。</p><h3 id="_4-接收端识别升级探测-不触发重启" tabindex="-1">4. 接收端识别升级探测，不触发重启 <a class="header-anchor" href="#_4-接收端识别升级探测-不触发重启" aria-label="Permalink to &quot;4. 接收端识别升级探测，不触发重启&quot;">​</a></h3><p><code>relay_dialer.go</code> / <code>ice_dialer.go</code> 收到 <code>HANDSHAKE_SYN</code> 时，<code>isActive</code> 分支里先看 <code>hs.IsUpgradeProbe</code>：</p><ul><li><strong>true</strong>：不调用 <code>onRestart()</code>。正常回 ACK、走 OFFER/ANSWER 交换，但交换结果只喂给发起方对应 <code>attemptID</code> 的 <code>shadowICEDialer</code>，不触碰当前 <code>Probe</code> 的主状态机、不碰现有 WireGuard 配置。</li><li><strong>false 或字段不存在</strong>（兼容旧版本）：保持现在的行为不变——宽限期内当重传，超出宽限期触发重启。</li></ul><h3 id="_5-只有-initiator-发起升级" tabindex="-1">5. 只有 initiator 发起升级 <a class="header-anchor" href="#_5-只有-initiator-发起升级" aria-label="Permalink to &quot;5. 只有 initiator 发起升级&quot;">​</a></h3><p>沿用现有的 <code>isInitiator(p.localId, p.remoteId)</code> 判断，避免两端同时探测、同时想切换造成竞态。</p><h2 id="备选方案" tabindex="-1">备选方案 <a class="header-anchor" href="#备选方案" aria-label="Permalink to &quot;备选方案&quot;">​</a></h2><ul><li><strong>保持全量重启，只是拉长 <code>upgradeBaseInterval</code> / 提高退避上限</strong>：治标不治本。Clash 一类环境下 ICE 永远打不通，无论多久重试一次，每次都会真中断一下，只是频率变低。</li><li><strong>先探测，成功了再触发一次&quot;干净的&quot;整段重启去完成切换</strong>：仍然要经历一次真实中断，比 make-before-break 差，只是没有 IsUpgradeProbe 这个字段这么&quot;干净&quot;。</li><li><strong>relay-ready 之后永远不再尝试直连</strong>：省事，但违背&quot;ICE 与 relay 赛跑&quot;的设计初衷，网络条件变好之后也升级不回直连，长期占用中继资源。</li></ul><h2 id="落地步骤" tabindex="-1">落地步骤 <a class="header-anchor" href="#落地步骤" aria-label="Permalink to &quot;落地步骤&quot;">​</a></h2><ol><li><code>internal/proto/signal.proto</code> / <code>internal/signal/signal.go</code> 加 <code>IsUpgradeProbe</code> + <code>AttemptID</code> 字段（<code>AttemptID</code> 是 ADR-0006 留的坑，这次一起填，两者本来就要配合使用）。</li><li>新增 <code>shadowICEDialer</code>（很大程度上是 <code>ice_dialer.go</code> 的瘦身版本，去掉与 <code>StateMachine</code>/<code>configurator</code> 的耦合）。</li><li><code>probe_upgrade.go</code> 的 <code>tryUpgrade()</code> 改为驱动 <code>shadowICEDialer</code>，不再调用 <code>restart()</code>。</li><li><code>relay_dialer.go</code> / <code>ice_dialer.go</code> 的 SYN 处理分支加 <code>IsUpgradeProbe</code> 判断与对应的接收侧响应路径。</li><li>确认/复用 <code>configurator.SetEndpoint</code> 的原地切换路径不会意外触发 <code>RegisterPeer</code>（AllowedIPs 重新下发）。</li></ol><h2 id="测试计划" tabindex="-1">测试计划 <a class="header-anchor" href="#测试计划" aria-label="Permalink to &quot;测试计划&quot;">​</a></h2><ul><li><strong>单测</strong>：<code>shadowICEDialer</code> 失败时，现有 <code>Probe</code> 的状态机、WireGuard peer 配置全程不变（mock provisioner 断言 <code>RegisterPeer</code>/<code>RemovePeer</code> 调用次数为 0）。</li><li><strong>单测</strong>：<code>shadowICEDialer</code> 成功时，只调用一次 <code>SetEndpoint</code>，不调用 <code>RegisterPeer</code>。</li><li><strong>单测</strong>：接收端收到 <code>IsUpgradeProbe: true</code> 的 SYN，不触发 <code>onRestart</code>；收到 <code>false</code>/无该字段的 SYN，行为与现在一致（回归保护）。</li><li><strong>集成</strong>：两节点 relay-ready 后人为切断 ICE（比如让 STUN 不可达，模拟 Clash 场景），跑满几个退避周期，relay 数据面应全程不中断（ping/流量不丢包），日志里应能看到多次升级尝试失败但连接保持稳定。</li><li><strong>真机回归</strong>：cloud-node-1 这个环境直接验证——在本文落地之前，这个环境永远等不到&quot;稳定超过 2 分钟、不撞升级窗口&quot;的干净测试窗口，这本身就是最直接的验收标准之一。</li></ul><h2 id="待确认的问题" tabindex="-1">待确认的问题 <a class="header-anchor" href="#待确认的问题" aria-label="Permalink to &quot;待确认的问题&quot;">​</a></h2><ol><li>升级失败的退避计数（<code>upgradeTries</code>）要不要在多次&quot;shadow 尝试失败&quot;之间持续累加到 30 分钟封顶？现有实现里 <code>p.restart()</code> 会重置探测状态机，<code>upgradeTries</code> 是否连带被清零还需要确认；改成不重启主探测之后，这个计数的生命周期应该更自然地贴着 <code>Probe</code> 本身，需要在实现时核对现有代码有没有意外清零的路径。</li><li><code>shadowICEDialer</code> 要不要复用主连接同一个 UDP 端口（<code>wg-port</code>）做候选收集，还是需要独立端口？复用端口能省一次 NAT 打洞，但要确认不会和主 relay/ICE 连接的收发路径混在一起。</li><li>接收端因为 <code>IsUpgradeProbe</code> 走的是独立于主 <code>Probe</code> 状态机的响应路径，这部分临时状态（谁在跟谁做后台探测）要不要设过期清理，避免异常/恶意节点通过反复发起假的升级探测消耗接收端资源——可以先简单加一条&quot;同一 remoteId 同时只允许一个 shadow 探测在途&quot;的限流。</li></ol><h2 id="决策记录-2026-10-03-实现时敲定" tabindex="-1">决策记录（2026-10-03，实现时敲定） <a class="header-anchor" href="#决策记录-2026-10-03-实现时敲定" aria-label="Permalink to &quot;决策记录（2026-10-03，实现时敲定）&quot;">​</a></h2><ol><li><strong><code>upgradeTries</code> 生命周期：维持现状</strong>。核对结果：restart 从不清零（<code>cancelUpgrade(false)</code> 只拆 timer），仅 ICE 成功（<code>cancelUpgrade(true)</code>）与 <code>Close</code> 清零——恰好就是想要的语义，无需改动。</li><li><strong>UDP 端口：复用共享 <code>FilteringUDPMux</code></strong>（与主 ICE 拨号器同一套 UDP socket，pion 按 ufrag/pwd 分流），影子 agent 自生成独立 ufrag/pwd，不开新端口。多个 agent 共用一个 mux 与今天&quot;每 peer 一个 agent&quot;同量级，且仅 relayed peer 的 60 s 尝试窗口内存在。</li><li><strong>接收端限流：每 remoteId 同时最多 1 个在途 shadow</strong>（实现于 <code>handleShadowSignal</code>）。在途期间后续带标记 SYN 只由既有 shadow 应答、不新开；60 s 尝试预算 + probe <code>Close</code>/restart 全量回收，不做更细的过期清理。</li></ol><p>实现落点：<code>internal/server/transport/probe_shadow_upgrade.go</code>（shadow 拨号器）、<code>probe_upgrade.go</code>（<code>tryUpgrade</code> 改驱动 shadow，不再 <code>restart</code>）、<code>signal.Handshake.IsUpgradeProbe/AttemptID</code> 与 <code>Offer.AttemptID</code>（信令标记，旧节点 JSON 反序列化自动忽略）。</p>`,44)])])}const g=o(d,[["render",i]]);export{u as __pageData,g as default};
